contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address target, uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(target != address(c));
        require(address(this).balance >= value);

        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cBefore = address(c).balance;
        uint targetBefore = target.balance;

        bool reverted;
        c.sendMoney(target, value, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert((!reverted && address(c).balance == cBefore - value && target.balance == targetBefore + value && c.depositsCount() == depositsBefore)
            || (reverted && address(c).balance == cBefore && target.balance == targetBefore && c.depositsCount() == depositsBefore));
    }
}

